// Some portions generated by Claude Code
package org.eclipse.rdf4j.workbench.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.io.ByteArrayOutputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;

import org.eclipse.rdf4j.rio.helpers.RioCompression;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

class QueryStreamCompressionTest {

	@ParameterizedTest
	@ValueSource(strings = { "br", "gzip", "deflate", "zstd" })
	void aFlushedRecordReachesTheServletStream(String coding) throws Exception {
		RioCompression compression = RioCompression.forContentEncoding(coding).orElseThrow();
		assumeTrue(compression.isAvailable(), coding + " is not available on this platform");
		MockHttpServletRequest request = new MockHttpServletRequest("POST", "/query");
		request.addHeader("Accept-Encoding", coding);
		MockHttpServletResponse response = new MockHttpServletResponse();
		RecordingOutputStream target = new RecordingOutputStream();

		OutputStream stream = QueryStreamCompression.open(request, response, target);
		assertThat(response.getHeader("Content-Encoding")).isEqualTo(coding);
		int flushesBefore = target.flushes;
		stream.write("{\"type\":\"progress\"}\n".getBytes(StandardCharsets.UTF_8));
		stream.flush();

		assertThat(target.flushes).as("the servlet stream is flushed, so the record reaches the socket")
				.isGreaterThan(flushesBefore);
		assertThat(target.bytes.size()).isPositive();
	}

	private static final class RecordingOutputStream extends OutputStream {
		private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		private int flushes;

		@Override
		public void write(int value) {
			bytes.write(value);
		}

		@Override
		public void write(byte[] buffer, int offset, int length) {
			bytes.write(buffer, offset, length);
		}

		@Override
		public void flush() {
			flushes++;
		}
	}
}
